lemma /*{:_inductionTrigger alphaEquivalence'(t1, t2, id1, id2)}*/ /*{:_induction t1, t2, id1, id2}*/ EqualTermsAreAlphaEquilvalent'(t1: LambdaTerm, t2: LambdaTerm, id1: seq<Id>, id2: seq<Id>)
