  decreases minim(lHeight(t1), lHeight(t2))
{
  match t1
  case {:split false} Var(x) =>
    {
      assert t1 == t2;
      ghost var y :| t2 == Var(y);
      assert x == y;
      ghost var r1 := findId(id1, x);
      ghost var r2 := findId(id2, y);
      assert r1 == r2;
      if r1 == None {
        assert x == y;
      }
      assert alphaEquivalence'(t1, t2, id1, id2);
    }
  case {:split false} Lambda(x, t1') =>
    {
      ghost var y, t2' :| t2 == Lambda(y, t2');
      assert y == x && t2' == t1';
      ghost var id1' := id1 + [x];
      ghost var id2' := id2 + [y];
      assert findId(id1', x) == Some(|id1'| - 1);
      assert findId(id1', x) == findId(id2', y);
      EqualTermsAreAlphaEquilvalent'(t1', t2', id1 + [x], id2 + [y]);
    }
  case {:split false} Application(t1', t1'') =>
    {
      ghost var t2', t2'' :| t2 == Application(t2', t2'');
      EqualTermsAreAlphaEquilvalent'(t1', t2', id1, id2);
      EqualTermsAreAlphaEquilvalent'(t1'', t2'', id1, id2);
    }
}

