lemma /*{:_inductionTrigger alphaEquivalence'(t, t2, id1, id2), substitution(t, x, LambdaTerm.Var(x'))}*/ /*{:_induction t, x, t2, id1, id2}*/ SubstAlphaEquivalence'(t: LambdaTerm, x: Id, x': Id, t2: LambdaTerm, id1: seq<Id>, id2: seq<Id>)
  requires |id1| == |id2| > 0
  requires !(x' in vars(t))
  requires id1[0] == x && id2[0] == x'
  requires forall i: int {:trigger id2[i]} {:trigger id1[i]} :: (0 <= i < |id1| ==> (id1[i] == x <==> id2[i] == x')) && (0 <= i < |id1| ==> id1[i] != x ==> id1[i] == id2[i])
  requires t2 == substitution(t, x, Var(x'))
  ensures alphaEquivalence'(t, t2, id1, id2)
  decreases lHeight(t)
{
  match t
  case {:split false} Application(t1a, t1b) =>
    {
      ghost var t2a := substitution(t1a, x, Var(x'));
      ghost var t2b := substitution(t1b, x, Var(x'));
      assert t2 == Application(t2a, t2b);
      SubstAlphaEquivalence'(t1a, x, x', t2a, id1, id2);
      SubstAlphaEquivalence'(t1b, x, x', t2b, id1, id2);
      assert alphaEquivalence'(t1a, t2a, id1, id2);
      assert alphaEquivalence'(t1b, t2b, id1, id2);
      assert alphaEquivalence'(t, t2, id1, id2);
    }
  case {:split false} Lambda(z, t1') =>
    {
      if z == x {
        assert t2 == t;
        ghost var id1' := id1 + [x];
        ghost var id2' := id2 + [x];
        forall y: nat | y in vars(t1')
          ensures findId(id1', y) == findId(id2', y)
        {
          if y != x {
            assert y in vars(t);
            assert y != x';
          }
        }
        EqualTermsAreAlphaEquilvalent'(t1', t1', id1', id2');
        assert alphaEquivalence'(t, t2, id1, id2);
      } else {
        ghost var t2' := substitution(t1', x, Var(x'));
        assert t2 == Lambda(z, t2');
        ghost var id1' := id1 + [z];
        ghost var id2' := id2 + [z];
        SubstAlphaEquivalence'(t1', x, x', t2', id1', id2');
        assert alphaEquivalence'(t1', t2', id1', id2');
      }
    }
  case {:split false} Var(z) =>
    {
      if z == x {
        assert t2 == Var(x');
        ghost var r1 := findId(id1, x);
        ghost var r2 := findId(id2, x');
        assert r1 != None;
        assert r1 == r2;
      } else {
        assert t2 == t;
        assert z != x';
