  assert [x1] == [] + [x1] && [x2] == [] + [x2];
}

lemma /*{:_inductionTrigger [x2] + id2, [x1] + id1, free(t2), free(t1)}*/ /*{:_inductionTrigger [x2] + id2, free(t2), x1 in id1, free(t1)}*/ /*{:_inductionTrigger [x1] + id1, x2 in id2, free(t2), free(t1)}*/ /*{:_inductionTrigger x2 in id2, free(t2), x1 in id1, free(t1)}*/ /*{:_induction t1, t2, id1, id2}*/ LambdaEquivalence'(t1: LambdaTerm, t2: LambdaTerm, x1: Id, x2: Id, id1: seq<Id>, id2: seq<Id>)
  requires alphaEquivalence'(t1, t2, id1, id2)
  requires x1 in free(t1) ==> x1 in id1
  requires x2 in free(t2) ==> x2 in id2
  ensures alphaEquivalence'(t1, t2, [x1] + id1, [x2] + id2)
  decreases t1, t2, x1, x2, id1, id2
{
  match t1
  case {:split false} Var(x) =>
    {
      ghost var y: Id :| t2 == Var(y);
      ghost var r1 := findId(id1, x);
      ghost var r2 := findId(id2, y);
      ghost var id1' := [x1] + id1;
      ghost var id2' := [x2] + id2;
      ghost var r1' := findId(id1', x);
      ghost var r2' := findId(id2', y);
      findId_prepend(id1, x, x1);
      findId_prepend(id2, y, x2);
      if r1 == None {
        assert x == y;
        assert x != x1;
        assert y != x2;
        assert !(x in id1');
        assert !(y in id2');
        assert r1' == None;
        assert r2' == None;
      } else {
        ghost var i1 :| r1 == Some(i1);
        assert r2 == Some(i1);
        ghost var new_pos := i1 + 1;
        assert id1'[new_pos] == x;
        assert r1' == Some(new_pos);
        assert id2'[new_pos] == y;
        assert r2' == Some(new_pos);
      }
    }
  case {:split false} Lambda(x, t1') =>
    {
      ghost var y: nat, t2': LambdaTerm :| t2 == Lambda(y, t2');
      ghost var id1' := id1 + [x];
      ghost var id2' := id2 + [y];
      LambdaEquivalence'(t1', t2', x1, x2, id1', id2');
      assert [x1] + id1 + [x] == [x1] + id1';
      assert [x2] + id2 + [y] == [x2] + id2';
    }
  case {:split false} Application(t1a, t1b) =>
    {
      ghost var t2a: LambdaTerm, t2b: LambdaTerm :| t2 == Application(t2a, t2b);
      LambdaEquivalence'(t1a, t2a, x1, x2, id1, id2);
      LambdaEquivalence'(t1b, t2b, x1, x2, id1, id2);
    }
}

lemma AlphaCongruenceLambda(y: Id, t1: LambdaTerm, t2: LambdaTerm)
  requires alphaEquivalence(t1, t2)
  ensures alphaEquivalence(Lambda(y, t1), Lambda(y, t2))
  decreases y, t1, t2
{
  assert [] + [y] == [y] == [y] + [];
  AlphaCongruenceLambda'(t1, t2, y, [], []);
}

lemma /*{:_inductionTrigger alphaEquivalence'(t1, t2, [y] + id1, [y] + id2)}*/ /*{:_induction t1, t2, id1, id2}*/ AlphaCongruenceLambda'(t1: LambdaTerm, t2: LambdaTerm, y: Id, id1: seq<Id>, id2: seq<Id>)
  requires alphaEquivalence'(t1, t2, id1, id2)
  ensures alphaEquivalence'(t1, t2, [y] + id1, [y] + id2)
  decreases minim(lHeight(t1), lHeight(t2))
{
  match t1 {
    case {:split false} Var(x) =>
      {
        ghost var z :| t2 == Var(z);
        ghost var r1 := findId(id1, x);
        ghost var r2 := findId(id2, z);
        ghost var id1' := [y] + id1;
        ghost var id2' := [y] + id2;
        ghost var r1' := findId(id1', x);
        ghost var r2' := findId(id2', z);
        findId_prepend(id1, x, x);
        findId_prepend(id2, y, x);
        if r1 == None {
          assert x == z;
          if x == y {
            assert id1'[0] == x;
            assert r1' == Some(0);
            assert id2'[0] == z;
            assert r2' == Some(0);
          } else {
            assert r1' == None;
            assert r2' == None;
          }
        } else {
          ghost var i1 :| r1 == Some(i1);
          ghost var new_pos := i1 + 1;
          assert id1'[new_pos] == x;
          assert r1' == Some(new_pos);
          assert id2'[new_pos] == z;
          assert r2' == Some(new_pos);
        }
      }
    case {:split false} Lambda(x, t1') =>
      {
        ghost var z, t2' :| t2 == Lambda(z, t2');
        AlphaCongruenceLambda'(t1', t2', y, id1 + [x], id2 + [z]);
        assert [y] + id1 + [x] == [y] + (id1 + [x]);
        assert [y] + id2 + [z] == [y] + (id2 + [z]);
      }
    case {:split false} Application(t1a, t1b) =>
      {
        ghost var t2a, t2b :| t2 == Application(t2a, t2b);
        AlphaCongruenceLambda'(t1a, t2a, y, id1, id2);
        AlphaCongruenceLambda'(t1b, t2b, y, id1, id2);
      }
  }
}

function substitution(t: LambdaTerm, x: Id, t': LambdaTerm): LambdaTerm
  decreases t, x, t'
{
  match t
  case Var(y) =>
    if y == x then
      t'
    else
      Var(y)
  case Lambda(y, t1) =>
    if y == x then
      t
    else
      Lambda(y, substitution(t1, x, t'))
  case Application(t1, t2) =>
    Application(substitution(t1, x, t'), substitution(t2, x, t'))
}

function caSubstitution(t: LambdaTerm, x: Id, t': LambdaTerm): LambdaTerm
  decreases t, x, t'
{
  var ids: seq<Id> := reunion(vars(t), vars(t'));
  reunionIncludesBothSets(vars(t), vars(t'));
  var safe_ids: seq<Id> := addition(x, ids);
  caSubstitution'(t, x, t', safe_ids)
}

lemma /*{:_inductionTrigger substitution(t1, x, t2)}*/ /*{:_induction t1, x, t2}*/ subsitutionOfVarDoesNotChangeHeightFORVARIABLES(t1: LambdaTerm, x: Id, t2: LambdaTerm)
  requires match t2 case Var(x) => true case _ /* _v0 */ => false
  ensures lHeight(substitution(t1, x, t2)) == lHeight(t1)
  decreases t1, x, t2
{
  ghost var t' := substitution(t1, x, t2);
  match t1 {
    case {:split false} Var(y) =>
      {
        assert lHeight(t') == lHeight(t1);
      }
    case {:split false} Lambda(y, t) =>
      {
        if y == x {
          assert t' == t1;
        } else {
          subsitutionOfVarDoesNotChangeHeightFORVARIABLES(t, x, t2);
        }
      }
    case {:split false} Application(t1, t2) =>
      {
      }
  }
}

lemma /*{:_inductionTrigger substitution(t1, x, t2)}*/ /*{:_induction t1, x, t2}*/ newIdsDueToSubstitution(t1: LambdaTerm, x: Id, t2: LambdaTerm, ids: seq<Id>)
  requires includes(ids, vars(t1))
  requires includes(ids, vars(t2))
  ensures includes(ids, vars(substitution(t1, x, t2)))
  decreases t1, x, t2, ids
{
  match t1
  case {:split false} Var(y) =>
    {
    }
  case {:split false} Lambda(y, t) =>
    {
      if y == x {
      } else {
        ghost var t' := substitution(t, x, t2);
        forall id2: nat | id2 < |vars(t)|
          ensures vars(t)[id2] in ids
        {
          assert vars(t)[id2] in vars(t1);
        }
        assert includes(ids, vars(t));
        newIdsDueToSubstitution(t, x, t2, ids);
        ghost var new_vars := addition(y, vars(t'));
        forall id2: nat | id2 < |new_vars|
          ensures new_vars[id2] in ids
        {
          ghost var elem := new_vars[id2];
          if elem == y {
            assert y in vars(t1);
          } else {
            assert elem in vars(t');
          }
        }
      }
    }
  case {:split false} Application(t1', t2') =>
    {
      ghost var sub_t1' := substitution(t1', x, t2);
      ghost var sub_t2' := substitution(t2', x, t2);
      forall id2: nat | id2 < |vars(t1')|
        ensures vars(t1')[id2] in ids
      {
        assert vars(t1')[id2] in vars(t1);
      }
      assert includes(ids, vars(t1'));
      forall id2: nat | id2 < |vars(t2')|
        ensures vars(t2')[id2] in ids
      {
        assert vars(t2')[id2] in vars(t1);
      }
      assert includes(ids, vars(t2'));
      newIdsDueToSubstitution(t1', x, t2, ids);
      newIdsDueToSubstitution(t2', x, t2, ids);
      ghost var new_vars := reunion(vars(sub_t1'), vars(sub_t2'));
      forall id2: nat | id2 < |new_vars|
        ensures new_vars[id2] in ids
      {
        ghost var elem := new_vars[id2];
        assert elem in vars(sub_t1') || elem in vars(sub_t2');
      }
    }
}

function caSubstitution'(t: LambdaTerm, x: Id, t': LambdaTerm, ids: seq<Id>): LambdaTerm
  requires allUnique(ids)
  requires var s1: seq<Id> := vars(t); allUnique(s1) && includes(ids, s1)
  requires var s2: seq<Id> := vars(t'); allUnique(s2) && includes(ids, s2)
  requires x in ids
  decreases lHeight(t)
{
  match t
  case Var(y) =>
    if y == x then
      t'
    else
      Var(y)
  case Lambda(y, t1) =>
    if y == x then
      t
    else if !(y in free(t')) then
      Lambda(y, caSubstitution'(t1, x, t', ids))
    else
      (var ids': seq<Id> := addAnUniqueId(ids); var vari: LambdaTerm := Var(ids'[0]); var t2: LambdaTerm := substitution(t1, y, vari); subsitutionOfVarDoesNotChangeHeightFORVARIABLES(t1, y, vari); varsOfALambdaIncludesVarsofASubLambda(t); newIdsDueToSubstitution(t1, y, vari, ids'); Lambda(ids'[0], caSubstitution'(t2, x, t', ids')))
  case Application(t1, t2) =>
    varsOfALambdaIncludesVarsofASubLambda(t);
    Application(caSubstitution'(t1, x, t', ids), caSubstitution'(t2, x, t', ids))
}

lemma LambdaNullifiesSubstitution(t: LambdaTerm, x: Id, t': LambdaTerm)
  ensures caSubstitution(Lambda(x, t), x, t') == Lambda(x, t)
  decreases t, x, t'
{
  ghost var lt := Lambda(x, t);
  ghost var ids := reunion(vars(lt), vars(t'));
  reunionIncludesBothSets(vars(lt), vars(t'));
  ghost var safe_ids := addition(x, ids);
  ghost var sub := caSubstitution'(lt, x, t', safe_ids);
  assert sub == caSubstitution(lt, x, t');
  match lt
  case {:split false} Lambda(y, t') =>
    {
      assert y == x;
      assert sub == lt;
    }
}

lemma /*{:_inductionTrigger caSubstitution'(t1, x, t2, ids)}*/ /*{:_inductionTrigger x in ids, vars(t2), vars(t1)}*/ /*{:_induction t1, x, t2, ids}*/ CaSubstitution'OfVarDoesNotChangeHeight(t1: LambdaTerm, x: Id, t2: LambdaTerm, ids: seq<Id>)
  requires match t2 case Var(_ /* _v1 */) => true case _ /* _v2 */ => false
  requires allUnique(ids)
  requires includes(ids, vars(t1)) && includes(ids, vars(t2)) && x in ids
  ensures lHeight(caSubstitution'(t1, x, t2, ids)) == lHeight(t1)
  decreases lHeight(t1)
{
  match t1 {
    case {:split false} Var(_ /* _v3 */) =>
      {
      }
    case {:split false} Lambda(y, t1') =>
      {
        if y == x {
        } else if !(y in free(t2)) {
          CaSubstitution'OfVarDoesNotChangeHeight(t1', x, t2, ids);
        } else {
          ghost var ids' := addAnUniqueId(ids);
          ghost var vari := Var(ids'[0]);
          ghost var t2' := substitution(t1', y, vari);
          subsitutionOfVarDoesNotChangeHeightFORVARIABLES(t1', y, vari);
          newIdsDueToSubstitution(t1', y, vari, ids');
          CaSubstitution'OfVarDoesNotChangeHeight(t2', x, t2, ids');
        }
      }
    case {:split false} Application(t1', t1'') =>
      {
        varsOfALambdaIncludesVarsofASubLambda(t1);
        CaSubstitution'OfVarDoesNotChangeHeight(t1', x, t2, ids);
        CaSubstitution'OfVarDoesNotChangeHeight(t1'', x, t2, ids);
      }
  }
}

lemma /*{:_inductionTrigger caSubstitution(t1, x, t2)}*/ /*{:_induction t1}*/ CaSubsitutionOfVarDoesNotChangeHeightFORVARIABLES(t1: LambdaTerm, x: Id, t2: LambdaTerm)
  requires match t2 case Var(_ /* _v4 */) => true case _ /* _v5 */ => false
  ensures lHeight(caSubstitution(t1, x, t2)) == lHeight(t1)
  decreases t1, x, t2
{
  ghost var ids := reunion(vars(t1), vars(t2));
  reunionIncludesBothSets(vars(t1), vars(t2));
  ghost var safe_ids := addition(x, ids);
  CaSubstitution'OfVarDoesNotChangeHeight(t1, x, t2, safe_ids);
}

lemma getVarCaSubstitution(M: LambdaTerm, x: Id, N: LambdaTerm)
  requires M.Var?
  ensures match M case Var(y) => if y == x then caSubstitution(M, x, N) == N else caSubstitution(M, x, N) == M
  decreases M, x, N
{
  ghost var ids := reunion(vars(M), vars(N));
  reunionIncludesBothSets(vars(M), vars(N));
  ghost var safe_ids := addition(x, ids);
  ghost var sub_M := caSubstitution'(M, x, N, safe_ids);
  assert sub_M == caSubstitution(M, x, N);
  match M
  case {:split false} Var(y) =>
    {
      if y == x {
        assert sub_M == N;
      } else {
        assert sub_M == M;
      }
    }
  case {:split false} _ /* _v6 */ =>
    {
      assert false;
    }
}

function bound(t: LambdaTerm): set<Id>
  decreases t
{
  match t
  case Var(_ /* _v0 */) =>
    {}
  case Lambda(x, t) =>
    {x} + bound(t)
  case Application(t1, t2) =>
    bound(t1) + bound(t2)
}

function free(t: LambdaTerm): set<Id>
  decreases t
{
  match t
  case Var(x) =>
    {x}
  case Lambda(x, t) =>
    free(t) - {x}
  case Application(t1, t2) =>
    free(t1) + free(t2)
}

function freeVec(t: LambdaTerm): seq<Id>
  ensures forall id: nat {:trigger id in freeVec(t)} {:trigger id in free(t)} :: id in free(t) ==> id in freeVec(t)
  decreases t
{
  match t
  case Var(x) =>
    [x]
  case Lambda(x, t) =>
    remove(freeVec(t), x)
  case Application(t1, t2) =>
    reunion(freeVec(t1), freeVec(t2))
}

lemma /*{:_inductionTrigger LambdaTerm.Lambda(y, t)}*/ /*{:_induction t}*/ NotInFreeAndNotFoundInLambdaSoNotInFree(t: LambdaTerm, x: Id, y: Id)
  requires x != y
  requires !(x in free(Lambda(y, t)))
  ensures !(x in free(t))
  decreases t, x, y
{
}

function vars(t: LambdaTerm): seq<Id>
  ensures allUnique(vars(t))
  decreases t
{
  match t
  case Var(x) =>
    [x]
  case Lambda(x, t') =>
    addition(x, vars(t'))
  case Application(t1, t2) =>
    reunion(vars(t1), vars(t2))
}

function varsSet(t: LambdaTerm): set<Id>
  ensures forall x: Id {:trigger x in vars(t)} {:trigger x in varsSet(t)} :: x in varsSet(t) <==> x in vars(t)
  decreases t
{
  match t
  case Var(x) =>
    {x}
  case Lambda(x, t') =>
    {x} + varsSet(t')
  case Application(t1, t2) =>
    varsSet(t1) + varsSet(t2)
}

lemma /*{:_inductionTrigger vars(t)}*/ /*{:_induction t}*/ varsOfALambdaIncludesVarsofASubLambda(t: LambdaTerm)
  ensures ghost var ids: seq<Id> := vars(t); match t case Var(x) => x in ids case Lambda(x, t') => x in ids && includes(ids, vars(t')) case Application(t1, t2) => includes(ids, vars(t1)) && includes(ids, vars(t2))
  decreases t
{
  ghost var ids := vars(t);
  match t
  case {:split false} Var(x) =>
    assert ids == [x];
  case {:split false} Lambda(x, t') =>
    assert ids == addition(x, vars(t'));
  case {:split false} Application(t1, t2) =>
    {
      assert ids == reunion(vars(t1), vars(t2));
      reunionIncludesBothSets(vars(t1), vars(t2));
    }
}

lemma /*{:_inductionTrigger vars(t)}*/ /*{:_induction t}*/ ASubLambdaOfAUniqueLambdaIsUnique(t: LambdaTerm)
  requires allUnique(vars(t))
  ensures match t case Var(_ /* _v1 */) => true case Application(t1, t2) => allUnique(vars(t1)) && allUnique(vars(t2)) case Lambda(_ /* _v2 */, t') => allUnique(vars(t'))
  decreases t
{
}

lemma /*{:_inductionTrigger free(t)}*/ /*{:_inductionTrigger vars(t)}*/ /*{:_induction t}*/ notInVarsSoNotInFree(t: LambdaTerm, x: Id)
  requires !(x in vars(t))
  ensures !(x in free(t))
  decreases t, x
{
}

function lHeight(t: LambdaTerm): nat
  decreases t
{
  match t
  case Var(x) =>
    1
  case Lambda(x, t') =>
    1 + lHeight(t')
  case Application(t1, t2) =>
    1 + max(lHeight(t1), lHeight(t2))
}

function findId(ids: seq<Id>, id: Id): Option<nat>
  ensures !(id in ids) <==> findId(ids, id) == None
  ensures id in ids <==> findId(ids, id) != None
  ensures id in ids <==> var pos: int /*{:_delayTriggerWarning}*/ {:trigger Some(pos)} :| findId(ids, id) == Some(pos); pos < |ids| && ids[pos] == id && (forall pos2: nat {:trigger ids[pos2]} :: pos < pos2 < |ids| ==> ids[pos2] != id) && forall pos3: nat {:trigger ids[pos3]} :: pos3 < |ids| && ids[pos3] == id ==> pos3 <= pos
  decreases ids
{
  if ids == [] then
    None
  else
    var len: int := |ids|; if ids[len - 1] == id then Some(len - 1) else findId(ids[..len - 1], id)
}

lemma /*{:_inductionTrigger findId([val] + ids, x)}*/ /*{:_induction ids, x}*/ findId_prepend(ids: seq<Id>, x: Id, val: Id)
  ensures findId([val] + ids, x) == match findId(ids, x) { case Some(i) => Some(i + 1) case None() => if x == val then Some(0) else None }
  decreases ids, x, val
{
  if ids == [] {
  } else {
    ghost var len := |ids|;
    ghost var prepended := [val] + ids;
    if ids[len - 1] == x {
      assert prepended[|prepended| - 1] == x;
    } else {
      assert prepended[..|prepended| - 1] == [val] + ids[..len - 1];
      findId_prepend(ids[..len - 1], x, val);
    }
  }
}

lemma /*{:_inductionTrigger W + P, y in W}*/ /*{:_induction W, P, y}*/ findId_concat_notInLeft(W: seq<Id>, P: seq<Id>, y: Id)
  requires !(y in W)
  ensures findId(W + P, y) == match findId(P, y) case Some(i) => Some(|W| + i) case None() => None
  decreases |P|
{
  if P == [] {
    assert W + P == W;
  } else {
    ghost var p := P[|P| - 1];
    ghost var P' := P[..|P| - 1];
    assert P == P' + [p];
    assert W + P == W + P' + [p];
    if p == y {
      assert findId(P, y) == Some(|P'|);
      assert |W + P'| == |W| + |P'|;
    } else {
      findId_concat_notInLeft(W, P', y);
      assert findId(P, y) == findId(P', y);
      assert findId(W + P, y) == findId(W + P', y);
    }
  }
}

lemma /*{:_inductionTrigger vars(t)}*/ /*{:_inductionTrigger free(t)}*/ /*{:_induction t}*/ FreeSubsetVars(t: LambdaTerm)
  ensures forall i: Id {:trigger i in vars(t)} {:trigger i in free(t)} :: i in free(t) ==> i in vars(t)
  decreases t
{
  match t {
    case {:split false} Var(_ /* _v3 */) =>
      {
      }
    case {:split false} Lambda(y, b) =>
      {
        FreeSubsetVars(b);
        varsOfALambdaIncludesVarsofASubLambda(t);
      }
    case {:split false} Application(a, b) =>
      {
        FreeSubsetVars(a);
        FreeSubsetVars(b);
        varsOfALambdaIncludesVarsofASubLambda(t);
      }
  }
}

ghost predicate allUnique(s: seq<Id>)
  decreases s
{
  forall id1: nat, id2: nat {:trigger s[id2], s[id1]} :: 
    id1 < id2 < |s| ==>
      s[id1] != s[id2]
}

lemma ElementNotInallUnique(s: seq<Id>, x: Id)
  requires !(x in s)
  requires allUnique(s)
  ensures allUnique([x] + s)
  decreases s, x
{
}

predicate includes(s1: seq<Id>, s2: seq<Id>)
  decreases s1, s2
{
  forall id2: nat {:trigger s2[id2]} :: 
    id2 < |s2| ==>
      exists id1: nat {:trigger s1[id1]} :: 
        id1 < |s1| &&
        s1[id1] == s2[id2]
}

function identitate(x: nat): nat
  decreases x
{
  x
}

lemma IncludesWitness(s: seq<Id>, i: nat)
  requires i < |s|
  ensures exists j: nat {:trigger s[j]} :: j < |s| && s[j] == s[i]
  decreases s, i
{
  assert s[i] in s;
  ghost var j: nat :| j < |s| && s[j] == s[i];
  assert j < |s| && s[j] == s[i];
}

lemma IncludesItself(s: seq<Id>)
  ensures includes(s, s)
  decreases s
{
  if !includes(s, s) {
    ghost var id2: nat :| id2 < |s| && !exists id1: nat {:trigger s[id1]} :: id1 < |s| && s[id1] == s[id2];
    assert s[id2] in s;
    ghost var id1: nat :| id1 < |s| && s[id1] == s[id2];
    assert false;
  }
}

function remove(s: seq<Id>, x: Id): seq<Id>
  requires allUnique(s)
  ensures !(x in remove(s, x))
  ensures allUnique(remove(s, x))
  ensures forall str: Id {:trigger str in s} {:trigger str in remove(s, x)} :: str in remove(s, x) ==> str in s
  ensures forall str: Id {:trigger str in remove(s, x)} {:trigger str in s} :: str in s && str != x ==> str in remove(s, x)
  ensures |s| - 1 <= |remove(s, x)| <= |s|
  ensures includes(s, remove(s, x))
  decreases s, x
{
  if s == [] then
    []
  else if s[0] == x then
    s[1..]
  else
    assert allUnique(remove(s[1..], x)); assert !(s[0] in remove(s[1..], x)); ElementNotInallUnique(remove(s[1..], x), s[0]); [s[0]] + remove(s[1..], x)
}

function addition(x: Id, s: seq<Id>): seq<Id>
  requires allUnique(s)
  ensures var s': seq<Id> := addition(x, s); allUnique(s') && x in s' && includes(s', s)
  decreases x, s
{
  if x in s then
    s
  else
    assert !(x in s); var s': seq<nat> := s + [x]; assert x in s'; assert allUnique(s'); assert forall id: nat {:trigger s'[id]} {:trigger s[id]} :: id < |s| ==> s[id] == s'[id]; s'
}

function reunion(s1: seq<Id>, s2: seq<Id>): seq<Id>
  requires allUnique(s1)
  requires allUnique(s2)
  ensures var s: seq<Id> := reunion(s1, s2); allUnique(s) && (forall str: Id {:trigger str in s2} {:trigger str in s1} {:trigger str in s} :: str in s ==> str in s1 || str in s2) && (forall str: Id {:trigger str in s} {:trigger str in s2} {:trigger str in s1} :: str in s1 || str in s2 ==> str in s) && |s| >= |s1| && |s| >= |s2|
  decreases s1, s2
{
  if s1 == [] then
    s2
  else
    [s1[0]] + reunion(remove(s1, s1[0]), remove(s2, s1[0]))
}

lemma /*{:_inductionTrigger reunion(s1, s2)}*/ /*{:_inductionTrigger allUnique(s2), allUnique(s1)}*/ /*{:_induction s1, s2}*/ reunionIncludesBothSets(s1: seq<Id>, s2: seq<Id>)
  requires allUnique(s1)
  requires allUnique(s2)
  ensures ghost var s: seq<Id> := reunion(s1, s2); includes(s, s1) && includes(s, s2)
  decreases s1, s2
{
  ghost var s := reunion(s1, s2);
  assert forall str: Id {:trigger str in s} {:trigger str in s1} :: str in s1 ==> str in s;
  assert forall str: Id {:trigger str in s} {:trigger str in s2} :: str in s2 ==> str in s;
  forall id2: nat | id2 < |s1|
    ensures exists id1: nat {:trigger s[id1]} :: id1 < |s| && s[id1] == s1[id2]
  {
    assert s1[id2] in s1;
    assert s1[id2] in s;
  }
  assert forall id2: nat {:trigger s1[id2]} :: id2 < |s1| ==> exists id1: nat {:trigger s[id1]} :: id1 < |s| && s[id1] == s1[id2];
  forall id2: nat | id2 < |s2|
    ensures exists id1: nat {:trigger s[id1]} :: id1 < |s| && s[id1] == s2[id2]
  {
    assert s2[id2] in s2;
    assert s2[id2] in s;
  }
  assert forall id2: nat {:trigger s2[id2]} :: id2 < |s2| ==> exists id1: nat {:trigger s[id1]} :: id1 < |s| && s[id1] == s2[id2];
}

lemma /*{:_inductionTrigger reunion(s1, s2)}*/ /*{:_induction s1, s2}*/ reunionIsGoodForWork(s1: seq<Id>, s2: seq<Id>)
  requires allUnique(s1)
  requires allUnique(s2)
  ensures allUnique(reunion(s1, s2))
  decreases s1, s2
{
  ghost var s := reunion(s1, s2);
  assert forall str: Id {:trigger str in s} {:trigger str in s2} {:trigger str in s1} :: str in s1 || str in s2 ==> str in s;
  assert forall str: Id {:trigger str in s} {:trigger str in s1} :: str in s1 ==> str in s;
  assert |s| >= |s1|;
  assert |s| >= |s1| && |s| >= |s2|;
}

lemma /*{:_inductionTrigger reunion(s1, s2)}*/ /*{:_inductionTrigger allUnique(s2), allUnique(s1)}*/ /*{:_induction s1, s2}*/ NotInReunionSoNotInBoth(s1: seq<Id>, s2: seq<Id>, x: Id)
  requires allUnique(s1) && allUnique(s2)
  requires !(x in reunion(s1, s2))
  ensures !(x in s1) && !(x in s2)
  decreases s1, s2, x
{
}

function highestId(s: seq<Id>): nat
  ensures s != [] ==> forall index: nat {:trigger s[index]} :: index < |s| ==> s[index] <= highestId(s)
  ensures s != [] ==> exists index: nat {:trigger s[index]} :: index < |s| && s[index] == highestId(s)
  ensures s == [] ==> highestId(s) == 0
  decreases s
{
  if s == [] then
    0
  else
    max(s[0], highestId(s[1..]))
}

function addAnUniqueId(s: seq<Id>): seq<Id>
  requires allUnique(s)
  ensures allUnique(addAnUniqueId(s))
  ensures includes(addAnUniqueId(s), s)
  ensures |addAnUniqueId(s)| == |s| + 1
  ensures !(addAnUniqueId(s)[0] in s)
  decreases s
{
  if s == [] then
    [0]
  else
    var s': seq<int> := [highestId(s) + 1] + s; assert forall id: nat {:trigger s[id]} :: id < |s| ==> s[id] == s'[id + 1]; s'
}

function max(a: nat, b: nat): nat
  ensures var maxi: nat := max(a, b); maxi >= a && maxi >= b && (maxi == a || maxi == b)
  decreases a, b
{
  if a > b then
    a
  else
    b
}

function minim(a: nat, b: nat): nat
  ensures minim(a, b) <= a && minim(a, b) <= b
  ensures minim(a, b) == a || minim(a, b) == b
  decreases a, b
{
  if a > b then
    b
  else
    a
}

const ReservedWords := [""AND"", ""OR"", ""NOT"", ""TRUE"", ""FALSE"", ""CERTIFICATE""]

predicate isStringAValidNumber(s: string)
  decreases s
{
  |s| > 0 &&
  (|s| > 1 ==>
    s[0] != '0') &&
  forall i: int {:trigger s[i]} | 0 <= i < |s| :: 
    s[i] in ""0123456789""
}

function natToString(n: nat): string
  ensures isStringAValidNumber(natToString(n))
  decreases n
{
  match n
  case 0 =>
    ""0""
  case 1 =>
    ""1""
  case 2 =>
    ""2""
  case 3 =>
    ""3""
  case 4 =>
    ""4""
  case 5 =>
    ""5""
  case 6 =>
    ""6""
  case 7 =>
    ""7""
  case 8 =>
    ""8""
  case 9 =>
    ""9""
  case _ /* _v0 */ =>
    natToString(n / 10) + natToString(n % 10)
}

function stringToNat(s: string): nat
  requires isStringAValidNumber(s)
  decreases |s|
{
  if |s| == 1 then
    match s[0]
    case '0' =>
      0
    case '1' =>
      1
    case '2' =>
      2
    case '3' =>
      3
    case '4' =>
      4
    case '5' =>
      5
    case '6' =>
      6
    case '7' =>
      7
    case '8' =>
      8
    case '9' =>
      9
  else
    stringToNat(s[..|s| - 1]) * 10 + stringToNat(s[|s| - 1 .. |s|])
}

lemma /*{:_inductionTrigger natToString(n)}*/ /*{:_induction n}*/ natToStringThenStringToNatIdem(n: nat)
  ensures stringToNat(natToString(n)) == n
  decreases n
{
}

lemma /*{:_inductionTrigger stringToNat(n)}*/ /*{:_inductionTrigger isStringAValidNumber(n)}*/ /*{:_induction n}*/ stringToNatThenNatToStringIdem(n: string)
  requires isStringAValidNumber(n)
  ensures natToString(stringToNat(n)) == n
  decreases n
{
}

datatype RefLambdaTerm = RefLambda(t': RefLambdaTerm) | FreeVar(x: Id) | BoundVar(n: nat) | App(t1: RefLambdaTerm, t2: RefLambdaTerm)

datatype circuitCell = AND(pos1: nat, pos2: nat) | OR(pos1: nat, pos2: nat) | NOT(pos: nat) | VARIABLE(x: string)

datatype Option<T> = Some(t: T) | None

type Id = nat

datatype LambdaTerm = Var(id: Id) | Lambda(x: Id, t: LambdaTerm) | Application(t1: LambdaTerm, t2: LambdaTerm)

type circuit = seq<circuitCell>

type stringNat = s: string
  | |s| > 0 && (|s| > 1 ==> s[0] != '0') && forall i: int | 0 <= i < |s| :: s[i] in ""0123456789""
  witness ""1""
")]

